-- ============================================================================
-- 07-seed-talwandi-sabo.sql
-- Real data from Talwandi Sabo Ah Punjab DB.xlsx (form responses)
-- 365 monthly reports across 31 institutes
-- Date range: 2025-03 to 2026-04
-- Default login password for all seeded users: Talwandi@2025
-- ============================================================================

-- 1. INSTITUTES (Talwandi Sabo, Bathinda)

INSERT INTO institutes (org_id, institute_name, institute_type, village_id, tehsil_id, district_id, is_active)
SELECT 'TS_CVH_TALWANDI_SABO', 'CVH Talwandi Sabo', 'CVH',
  (SELECT village_id FROM villages WHERE village_name = 'Talwandi Sabo' AND district_id = (SELECT district_id FROM districts WHERE district_name = 'Bathinda') LIMIT 1),
  (SELECT tehsil_id FROM tehsils WHERE tehsil_name = 'Talwandi Sabo' AND district_id = (SELECT district_id FROM districts WHERE district_name = 'Bathinda')),
  (SELECT district_id FROM districts WHERE district_name = 'Bathinda'), TRUE
WHERE NOT EXISTS (SELECT 1 FROM institutes WHERE org_id = 'TS_CVH_TALWANDI_SABO');

INSERT INTO institutes (org_id, institute_name, institute_type, village_id, tehsil_id, district_id, is_active)
