DO $BODY$ DECLARE
  v_inst_id INTEGER := (SELECT institute_id FROM institutes WHERE org_id = 'TS_CVH_NATHEHA' LIMIT 1);
  v_staff_id INTEGER := (SELECT staff_id FROM staff WHERE user_id = 'ts_cvh_natheha' LIMIT 1);
  v_report_id INTEGER;
BEGIN
  IF v_inst_id IS NULL OR v_staff_id IS NULL THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM monthly_reports WHERE institute_id = v_inst_id AND reporting_month = '2026-04') THEN RETURN; END IF;
  INSERT INTO monthly_reports (institute_id, reporting_month, start_date, end_date, receipt_number, submission_status, submitted_at, prepared_by)
  VALUES (v_inst_id, '2026-04', '2026-04-01', '2026-04-30', '393', 'Submitted', NOW(), v_staff_id)
  RETURNING report_id INTO v_report_id;

